
import pytest

from services.code_validation_service import (
    CodeValidationError,
    find_unresolved_names,
    validate_generated_python_change,
)

# The incorrect migration generated by the AI
incorrect_code = """
def checkout():
    return create_payment(100)
"""

# Correct migration with import
correct_code = """
from payment_api import create_payment

def checkout():
    return create_payment(100)
"""

print("Testing incorrect AI migration...")

unresolved = find_unresolved_names(incorrect_code)

print("Unresolved names:", unresolved)

assert "create_payment" in unresolved

print("PASS: Missing import detected")

print("\nTesting correct migration...")

unresolved = find_unresolved_names(correct_code)

print("Unresolved names:", unresolved)

assert unresolved == []

print("PASS: Correct migration accepted")


def test_generated_change_rejects_new_undefined_names():
    original = '''import requests

def fetch_post(post_id=1):
    response = requests.get(f"https://example.test/posts/{post_id}")
    response.raise_for_status()
    return response.json()
'''
    broken = '''import requests

def fetch_post(post_id=1):
    response.raise_for_status()
    return response.json()
'''

    with pytest.raises(CodeValidationError, match="introduces undefined names"):
        validate_generated_python_change(original, broken, "client.py")


def test_generated_change_allows_existing_undefined_names_if_not_worsened():
    original = "def fetch():\n    return legacy_client.get()\n"
    updated = "def fetch():\n    return legacy_client.get()\n"

    result = validate_generated_python_change(original, updated, "client.py")

    assert result["status"] == "passed"
